/// The message-map functions of window message `msg` (several classes may handle it).
pub fn msg_handlers(msg: u32) -> &'static [u64] {
    match msg {
        0x15a6 => &[0x8400f1d20],
        0x15a7 => &[0x840135b90],
        0x15a8 => &[0x840145150],
        0x15a9 => &[0x8400f8e40, 0x840146950],
        0x15aa => &[0x840083330, 0x8401468d0],
        0x163d => &[0x840089110],
        0x1679 => &[0x840144900],
        0x2261 => &[0x840089db0],
        0x244e => &[0x84008c0e0],
        _ => &[],
    }
}

